import{_ as d,o as r,c as o,a2 as a}from"./chunks/framework.DnrXFDHb.js";const q=JSON.parse('{"title":"从开工到点亮的12个节点，第13个超支陷阱","description":"","frontmatter":{"title":"从开工到点亮的12个节点，第13个超支陷阱","updated":"2026-08-22T00:00:00.000Z","visibility":"public"},"headers":[],"relativePath":"智算中心投建运/从开工到点亮的12个节点_第13个超支陷阱.md","filePath":"智算中心投建运/从开工到点亮的12个节点_第13个超支陷阱.md","lastUpdated":null}'),e={name:"智算中心投建运/从开工到点亮的12个节点_第13个超支陷阱.md"};function p(n,t,l,i,u,s){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="发布信息区-不上正文-仅供运营" tabindex="-1">发布信息区（不上正文，仅供运营） <a class="header-anchor" href="#发布信息区-不上正文-仅供运营" aria-label="Permalink to &quot;发布信息区（不上正文，仅供运营）&quot;">​</a></h1><p><strong>TOP1 标题</strong>：从开工到点亮的12个节点，和第13个没人告诉你的超支陷阱</p><p><strong>备选 TOP3</strong>：</p><ul><li>点亮≠交付：智算中心最贵的一段路，在送电之后（观点型）</li><li>你的智算中心为什么总在验收后超支？答案藏在电费单第二行（悬念型）</li></ul><p><strong>其余备选（标题矩阵共12个，覆盖十二型）</strong>：</p><ul><li>一个100MW智算中心，点亮后每月白烧两百多万？（数据型）</li><li>12个节点照表走，只有4个会爆雷（极简+判断）</li><li>干了20年地产，我用一张节点表看懂智算中心交付（体感/品牌型）</li><li>从竣备到满租要两年，从点亮到满载要多久？（冲突型）</li><li>智算中心交付清单：12个节点、4个雷区、1个现金流陷阱（工具型）</li><li>别让&quot;点亮&quot;骗了你：容量锁定成本正在吃掉智算中心的利润（警示型）</li><li>投资人看智算中心，别问哪天点亮，问哪天满载（投资型）</li><li>两部制电价下，智算中心的&quot;空转&quot;到底有多贵（问题型）</li><li>48%的开发商最怕的不是建不完，是电不来（一个数字+一个判断）</li></ul><p><strong>摘要（≤120字）</strong>：智算中心从开工到点亮要过12个节点，真正会爆雷的只有4个。但最贵的是第13个——点亮之后、满载之前，锁死的电力容量每月都在出血。附节点验收速查表，可直接打印。</p><p><strong>封面建议</strong>：一张工地夜景，远处变电站轮廓+近处亮起的机房灯光，压一行字&quot;点亮≠交付&quot;。</p><hr><h1 id="正文" tabindex="-1">正文 <a class="header-anchor" href="#正文" aria-label="Permalink to &quot;正文&quot;">​</a></h1><blockquote><p>说明一下：本文由 AI 辅助整理资料与初稿，但核心判断、数据口径和那几个&quot;你以为……其实……&quot;的转折，都来自我自己——一个干了 20 年地产基金、后来扎进电力交易和 HVDC 电源架构的老炮。说白了，AI 负责查资料，我负责想明白、说人话。如果哪段让你觉得&quot;这人真干过&quot;，那是我；如果哪段读着像机器，那是我没收住，欢迎骂我。</p></blockquote><p>我跟你讲个真事。</p><p>上个月，一个做智算中心的朋友给我打电话，语气特别高兴：&quot;点亮了！首期点亮了！&quot;</p><p>我在电话里问了他两个问题：上架率现在多少？基本电费按容量还是按需量报的？</p><p>电话那头沉默了大概五秒钟。他说：&quot;……这个还没顾上想。&quot;</p><p>我不是要扫他的兴。点亮当然是好事，值得喝一杯。但干了 20 年地产，我太熟悉这个时刻了——这就像当年商场拿到竣工备案那天，大家开香槟庆祝，可财务部的脸色是沉着的。因为他们知道：<strong>竣备不是终点，竣备是现金流出血的开始</strong>——招商没满，物业费、能耗费、贷款利息一天不停地往外流。</p><p>智算中心一模一样。只是流出速度更快，而且大多数人根本没把这笔账算进模型里。</p><p>这篇文章，我把智算中心从开工到点亮拆成 12 个节点，告诉你哪 4 个最容易爆雷；然后重点拆第 13 个——一个几乎没人写进投资测算的超支陷阱。文末有张速查表，可以直接打印贴墙。</p><h2 id="先上一张表-从开工到点亮的-12-个节点" tabindex="-1">先上一张表：从开工到点亮的 12 个节点 <a class="header-anchor" href="#先上一张表-从开工到点亮的-12-个节点" aria-label="Permalink to &quot;先上一张表：从开工到点亮的 12 个节点&quot;">​</a></h2><p>当年我们做商业地产，每个项目墙上都贴着一张节点表：拿地、开工、预售、封顶、竣备、开业。谁的节点谁签字，过了节点才能领下一笔工程款。智算中心也该有这么一张表，只是节点内容不一样——<strong>地产的关键路径是预售证，智算中心的关键路径是电</strong>。</p><table tabindex="0"><thead><tr><th>#</th><th>节点</th><th>关键动作</th><th>谁签字</th><th>最容易踩的坑</th></tr></thead><tbody><tr><td>1 ★</td><td>电力接入批复</td><td>用电报装、接入系统方案、电网评审</td><td>电网公司</td><td>把批复时间当&quot;确定项&quot;排进工期</td></tr><tr><td>2</td><td>土建开工</td><td>桩基、外电管沟走廊预留</td><td>总包</td><td>忘了给外电线路留走廊，后期开挖返工</td></tr><tr><td>3</td><td>主体封顶</td><td>结构验收</td><td>监理</td><td>为赶封顶牺牲机房层高与承重复核</td></tr><tr><td>4</td><td>电网配套工程</td><td>外电线路、上级变电站扩建</td><td>电网/政府</td><td>这活不在你手里，进度你说了不算</td></tr><tr><td>5 ★</td><td>主设备下单</td><td>变压器、开关柜、柴发、UPS/HVDC、冷机锁价锁交期</td><td>业主采购</td><td>下单晚一个月，交付晚一个季度</td></tr><tr><td>6</td><td>主设备到货</td><td>到货验收、抽检</td><td>业主+监理</td><td>到货≠合格，抽检流于形式</td></tr><tr><td>7</td><td>供配电安装</td><td>变配电、母线、列头柜</td><td>机电总包</td><td>与装修交叉施工，成品保护扯皮</td></tr><tr><td>8</td><td>制冷系统安装</td><td>冷机、液冷管路、CDU</td><td>机电总包</td><td>液冷管路试压冲洗不净，后患无穷</td></tr><tr><td>9</td><td>弱电与网络</td><td>综合布线、安防、DCIM</td><td>弱电分包</td><td>光纤熔接点验收不逐点测</td></tr><tr><td>10 ★</td><td>系统联调</td><td>假负载带载测试、柴发切换、ATS 演练</td><td>业主+第三方</td><td>为赶点亮跳过满载测试</td></tr><tr><td>11 ★</td><td>并网验收送电</td><td>电网验收、受电、正式送电</td><td>电网公司</td><td>送电即起表，电费开始按天计</td></tr><tr><td>12</td><td>IT 上架点亮</td><td>服务器进场、上架、点亮、首期算力投运</td><td>运营方</td><td>点亮即宣传，上架率没人追</td></tr></tbody></table><p>这张表照着走，大部分项目不会出大事。但干工程的都知道：<strong>流程节点决定快慢，风险节点决定生死</strong>。12 个里面，真正会爆雷的只有 4 个——表里的 ★。</p><h2 id="雷区一-电力接入批复——你以为在排工期-其实在排队" tabindex="-1">雷区一：电力接入批复——你以为在排工期，其实在排队 <a class="header-anchor" href="#雷区一-电力接入批复——你以为在排工期-其实在排队" aria-label="Permalink to &quot;雷区一：电力接入批复——你以为在排工期，其实在排队&quot;">​</a></h2><p>全球范围内，48% 的数据中心开发商把并网延迟列为首要制约（Turner &amp; Townsend 数据中心建设成本指数，2025-2026 版）。注意，不是成本，不是技术，是<strong>电进不来</strong>。</p><p>这个场景地产人太熟了。当年拿了一块好地，商场图纸都画好了，市政管线要五年才到位——你总不能先开业再接水管吧？</p><p>现在智算中心的&quot;水管&quot;就是变电站和外电线路。芯片 18 个月换代一次，接入系统批复加配套线路建设，按年算。<strong>所以第一雷区的红线只有一条：接入批复时间必须倒排进总工期，而且按悲观口径排。</strong></p><h2 id="雷区二-主设备交期——下单晚一个月-交付晚一个季度" tabindex="-1">雷区二：主设备交期——下单晚一个月，交付晚一个季度 <a class="header-anchor" href="#雷区二-主设备交期——下单晚一个月-交付晚一个季度" aria-label="Permalink to &quot;雷区二：主设备交期——下单晚一个月，交付晚一个季度&quot;">​</a></h2><p>第二个雷在供应链。Turner &amp; Townsend 同一份报告里，只有 19% 的受访者相信供应商能在 2026 年兑现交付时间表。液冷高密度方案相对同 IT 容量的传统风冷，在美国市场有 7% 到 10% 的成本溢价（该报告口径）。</p><p>行业里也在用预制化、模块化抢时间：华为电力模块把交付周期从 28 周压到 18 周（华为数字能源，2025 年 5 月），浪潮的算力工厂方案做到 120 天建设投运（OFweek，2026 年 1 月）。</p><p>但你注意一个细节：<strong>预制化压缩的是工厂和施工的时间，不是电网的时间</strong>。节点 5 的坑在于，很多项目把变压器、柴发、冷机当成&quot;标准采购&quot;，等土建差不多了才下单。高功率变压器和开关柜的交期是以季度计的，晚下单一个月，整个项目的关键路径就往后挪一个季度。</p><p>这跟当年抢预售节点一个道理：预售证不等人，总包队伍、材料锁价都得提前半年排布。<strong>谁先锁资源，谁就有工期。</strong></p><h2 id="雷区三-系统联调——假负载测试是最容易被-优化-掉的钱" tabindex="-1">雷区三：系统联调——假负载测试是最容易被&quot;优化&quot;掉的钱 <a class="header-anchor" href="#雷区三-系统联调——假负载测试是最容易被-优化-掉的钱" aria-label="Permalink to &quot;雷区三：系统联调——假负载测试是最容易被&quot;优化&quot;掉的钱&quot;">​</a></h2><p>节点 10 是整个交付里最烧脑也最容易被砍预算的一环：假负载带载测试。</p><p>说白了，就是租一堆&quot;假服务器&quot;（负载箱），把供配电、制冷系统按满载甚至超载跑一遍，验证柴发能不能在规定秒内带起负载、ATS 切换会不会闪断、液冷系统压不压得住峰值。</p><p>为什么要烧这个钱？Uptime Institute 的年度中断分析报告（2026 版）给了一组数：57% 的受访者最近一次重大中断损失超过 10 万美元，约两成超过 100 万美元；而电力系统仍是中断的首要诱因，占 45%。<strong>中断的第一原因是电，而电的隐患只能在上架前的带载测试里暴露。</strong></p><p>可现实里，工期一紧，最先被&quot;优化&quot;的就是满载测试——&quot;先点亮，测试后面补&quot;。这就像商场开业前把消防演习省了：平时看不出来，出事就是大事。</p><h2 id="雷区四-并网验收——送电那天-计费就开始了" tabindex="-1">雷区四：并网验收——送电那天，计费就开始了 <a class="header-anchor" href="#雷区四-并网验收——送电那天-计费就开始了" aria-label="Permalink to &quot;雷区四：并网验收——送电那天，计费就开始了&quot;">​</a></h2><p>第四个雷区最安静，也最容易被忽视。</p><p>节点 11 送电验收通过，所有人松了一口气，准备节点 12 的点亮仪式。但有一件事在送电那一刻已经发生：<strong>电网开始计费了</strong>。</p><p>这就引出第 13 个节点——不在任何工程进度表上，却在每一张电费单上。</p><h2 id="第-13-个节点-点亮之后、满载之前-容量在替你烧钱" tabindex="-1">第 13 个节点：点亮之后、满载之前，容量在替你烧钱 <a class="header-anchor" href="#第-13-个节点-点亮之后、满载之前-容量在替你烧钱" aria-label="Permalink to &quot;第 13 个节点：点亮之后、满载之前，容量在替你烧钱&quot;">​</a></h2><p>先把口径说清楚。按国家发改委《关于第三监管周期省级电网输配电价及有关事项的通知》（发改价格〔2023〕526 号），用电容量 315 千伏安及以上的工商业用户执行两部制电价：电费 = 电度电费（按实际用电量）+ 容（需）量电费（按你占用的电网资源）。</p><p>后面这第二行，就是圈内说的&quot;基本电费&quot;。智算中心这种体量，一个 100MVA 的项目，报装容量批下来、送电完成那天起，这笔钱就按月计收——<strong>不管你机柜里有没有服务器</strong>。</p><p>你说我选按需量计费不就完了？没那么简单。按国家发改委办公厅 2016 年《关于完善两部制电价用户基本电价执行方式的通知》，合同最大需量核定值低于变压器容量总和 40% 的，按 40% 核定。也就是说，就算你一台服务器没上，按需量计费的下限也是报装容量的四成。</p><p>来，算笔账。</p><p><strong>本文采用口径</strong>：以浙江第三监管周期输配电价为例（财新 2023 年 5 月报道口径），110 千伏等级容量电价 26 元/千伏安·月；526 号文统一需量电价为容量电价的 1.6 倍，即约 41.6 元/千瓦·月。各省标准不同，量级一致。</p><p>一个 100MVA 报装的智算中心，从送电到满载的爬坡期里，容量锁定成本是这样的：</p><table tabindex="0"><thead><tr><th>爬坡期（上架率爬升）</th><th>按容量计费</th><th>按需量计费（40% 下限核定）</th></tr></thead><tbody><tr><td>6 个月</td><td>约 1,560 万元</td><td>约 1,000 万元</td></tr><tr><td>12 个月</td><td>约 3,120 万元</td><td>约 2,000 万元</td></tr><tr><td>18 个月</td><td>约 4,680 万元</td><td>约 3,000 万元</td></tr></tbody></table><p>（测算假设：100,000 千伏安 × 26 元/千伏安·月；需量按 40% 下限即 4 万千瓦 × 41.6 元/千瓦·月。为突出量级，未计上架率逐月爬升带来的需量递增，实际按需量口径会略高于此。）</p><p><strong>也就是说，点亮到满载之间每拖一年，一个 100MW 级项目要为&quot;没在用的电容量&quot;付出去两三千万。</strong> 这笔钱不在土建变更里，不在机电签证里，不在任何一张工程结算单里——所以它在绝大多数投资测算里根本不存在。</p><p>还有更隐蔽的一层。还记得节点 10 的带载测试吗？调试期间负载瞬间冲高，如果实际最大需量超过合同核定值 105%，超出部分基本电费<strong>加倍收取</strong>（2016 年通知原文）。调试期本来就是负载最不稳定的时候——很多项目的第一笔&quot;超额电费&quot;，就是在联调那个月交出来的学费。</p><p>干了 20 年地产，我见过太多项目死在&quot;竣备之后、满租之前&quot;的现金流断档上。现在看智算中心，同样的剧本正在重演，只是主角从招商率换成了上架率，从物业费换成了基本电费。</p><p><strong>点亮≠交付。真正的交付线，是上架率爬过现金流平衡点的那一天。</strong></p><h2 id="这个陷阱怎么躲-四条-都能落地" tabindex="-1">这个陷阱怎么躲？四条，都能落地 <a class="header-anchor" href="#这个陷阱怎么躲-四条-都能落地" aria-label="Permalink to &quot;这个陷阱怎么躲？四条，都能落地&quot;">​</a></h2><p><strong>第一，分期报装、分期送电。</strong> 别把 100MVA 一次性全送。按上架计划分两到三期报装受电，没上架的容量不送电、不起表。电网对减容、暂停有成熟机制——2016 年通知明确，暂停用电每自然年累计可达六个月，暂停部分免收基本电费。</p><p><strong>第二，爬坡期按需量计费，核定值逐月跟着上架率调。</strong> 合同最大需量核定值可以按月申请变更。记住 40% 的下限，剩下的精细化空间交给运营。</p><p><strong>第三，把负荷率优惠当目标来运营。</strong> 526 号文规定，按需量计费的用户每月每千伏安用电量达到 260 千瓦时及以上，当月需量电价打九折。这条本来是给高负荷率工厂的奖励，对智算中心来说，它逼着你把&quot;电用满&quot;当成运营 KPI——这本来就是下一篇要讲的事。</p><p><strong>第四，把&quot;送电日&quot;到&quot;满载日&quot;的爬坡期电费，显式写进投资模型。</strong> 我给项目做测算时，这一栏单列，叫&quot;容量空置成本&quot;。就像地产模型里竣备到满租之间的持有成本一样——你不写它，它不会消失，只会在第二年变成&quot;意外超支&quot;。</p><h2 id="所以呢-这事对资产意味着什么" tabindex="-1">所以呢？这事对资产意味着什么 <a class="header-anchor" href="#所以呢-这事对资产意味着什么" aria-label="Permalink to &quot;所以呢？这事对资产意味着什么&quot;">​</a></h2><p>如果你在评估一个智算中心项目，别问&quot;哪天点亮&quot;，问三个问题：</p><p>接入批复拿到没有，悲观口径排到几月？上架率爬坡计划是怎么定的，谁背这个指标？现金流模型里，送电到满载之间的容量成本算了没有？</p><p>三个问题都有答案的项目，不一定赚钱；但答不上来的项目，一定在赌。</p><p>这几年 AI 基建很热，热到很多人以为这是个算力生意。我干了 20 年资产，看到的恰恰相反：<strong>这是个现金流管理生意——谁的爬坡期短，谁的容量空置少，谁的资产就值钱。</strong></p><h2 id="附-节点验收速查表-可打印" tabindex="-1">附：节点验收速查表（可打印） <a class="header-anchor" href="#附-节点验收速查表-可打印" aria-label="Permalink to &quot;附：节点验收速查表（可打印）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>节点</th><th>验收红线（不过不签字）</th></tr></thead><tbody><tr><td>1 ★</td><td>电力接入批复</td><td>批复文件到手，时间倒排入总工期</td></tr><tr><td>2</td><td>土建开工</td><td>外电管沟走廊预留完成</td></tr><tr><td>3</td><td>主体封顶</td><td>机房层高、承重复核通过</td></tr><tr><td>4</td><td>电网配套工程</td><td>外电线路进度与内部工期对齐</td></tr><tr><td>5 ★</td><td>主设备下单</td><td>交期书面锁定，违约条款明确</td></tr><tr><td>6</td><td>主设备到货</td><td>抽检合格，不是&quot;到货即验收&quot;</td></tr><tr><td>7</td><td>供配电安装</td><td>绝缘、耐压试验记录齐全</td></tr><tr><td>8</td><td>制冷系统安装</td><td>液冷管路试压、冲洗、保压合格</td></tr><tr><td>9</td><td>弱电与网络</td><td>光纤熔接点逐点测试</td></tr><tr><td>10 ★</td><td>系统联调</td><td>满载假负载测试完成，柴发切换实测合格；调试月需量申报已核</td></tr><tr><td>11 ★</td><td>并网验收送电</td><td>送电日前完成计费方式（容量/需量）比选与申报</td></tr><tr><td>12</td><td>IT 上架点亮</td><td>上架率爬坡计划同步签发，责任到人</td></tr><tr><td>13</td><td>（隐藏节点）</td><td>现金流模型已计入容量空置成本</td></tr></tbody></table><hr><p>数据来源： [1] Turner &amp; Townsend《数据中心建设成本指数 2025-2026》（2025.11）｜48% 开发商将并网延迟列为首要制约、2026 年供应商按期交付信心仅 19%、液冷成本溢价 7-10% [2] 国家发改委《关于第三监管周期省级电网输配电价及有关事项的通知》（发改价格〔2023〕526 号，2023.05）｜两部制电价适用范围、需容电价比 1.6、负荷率九折优惠 [3] 国家发改委办公厅《关于完善两部制电价用户基本电价执行方式的通知》（2016.06）｜需量核定 40% 下限、超 105% 加倍、减容暂停机制 [4] Uptime Institute《Annual Outage Analysis 2026》（2026.05）｜57% 重大中断损失超 10 万美元、电力占中断诱因 45% [5] 财新《新一轮省级电网输配电价公布》（2023.05）；华为数字能源（2025.05）；OFweek（2026.01）｜浙江分电压等级容量电价、预制化交付周期案例</p><p>⚠️ 风险提示：各省容（需）量电价标准与电网接入政策存在差异，测算需按项目所在地口径重算；上架率爬坡不及预期的经营风险。本文仅作产业研究，不构成任何投资建议。</p><p>关注「算电协同研习社」，下一篇我们拆：点亮之后怎么算账——上架率、PUE 与算力利用率的联动。</p><hr><h1 id="附-发布包备查-不上正文" tabindex="-1">附：发布包备查（不上正文） <a class="header-anchor" href="#附-发布包备查-不上正文" aria-label="Permalink to &quot;附：发布包备查（不上正文）&quot;">​</a></h1><p><strong>金句（文中已加粗，可单独做海报/切片）</strong>：</p><ol><li>竣备不是终点，竣备是现金流出血的开始。</li><li>地产的关键路径是预售证，智算中心的关键路径是电。</li><li>预制化压缩的是工厂和施工的时间，不是电网的时间。</li><li>中断的第一原因是电，而电的隐患只能在上架前的带载测试里暴露。</li><li>点亮≠交付。真正的交付线，是上架率爬过现金流平衡点的那一天。</li><li>谁的爬坡期短，谁的容量空置少，谁的资产就值钱。</li></ol><p><strong>图表建议</strong>：</p><ul><li>图1：12 节点泳道图（业主/总包/电网三条泳道，4 个 ★ 节点标红）——回答&quot;全流程谁在卡谁&quot;。</li><li>图2：第 13 节点敏感性表（正文已有，可做柱状图）——回答&quot;爬坡期每多半年烧多少钱&quot;。</li><li>图3：爬坡期现金流曲线示意（电容量计费和上架率两条线的剪刀差）——回答&quot;出血窗口有多长&quot;。</li></ul><p><strong>AI 标识提醒</strong>：发布前请在公众号后台完成 AI 生成内容标识（依据《人工智能生成合成内容标识办法》）。</p>',76)])])}const g=d(e,[["render",p]]);export{q as __pageData,g as default};
